package theme

import (
	"encoding/json"
	"fmt"
	"image/color"
	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// FromJSON parses a JSON string and returns a Theme. On parse error, returns the default theme along with the error.
// The JSON structure supports Colors (generic and variant-specific), Sizes, Fonts, and Icons.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme. On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var jsonTheme jsonThemeData
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&jsonTheme); err != nil {
		return defaultTheme, err
	}

	return &customJSONTheme{
		data:    jsonTheme,
		variant: VariantDark,
	}, nil
}

type jsonThemeData struct {
	Colors      map[string]string  `json:"Colors"`
	ColorsDark  map[string]string  `json:"Colors-dark"`
	ColorsLight map[string]string  `json:"Colors-light"`
	Sizes       map[string]float32 `json:"Sizes"`
	Fonts       map[string]string  `json:"Fonts"`
	Icons       map[string]string  `json:"Icons"`
}

type customJSONTheme struct {
	data    jsonThemeData
	variant fyne.ThemeVariant
}

func (t *customJSONTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Store the variant for other methods that need it
	t.variant = variant

	colorName := string(name)

	// Check variant-specific colors first
	var hexStr string
	var found bool

	if variant == VariantDark && t.data.ColorsDark != nil {
		hexStr, found = t.data.ColorsDark[colorName]
	} else if variant == VariantLight && t.data.ColorsLight != nil {
		hexStr, found = t.data.ColorsLight[colorName]
	}

	// If not found in variant-specific, check generic Colors
	if !found && t.data.Colors != nil {
		hexStr, found = t.data.Colors[colorName]
	}

	// If found, parse the hex color
	if found {
		if c, err := parseHexColor(hexStr); err == nil {
			return c
		}
	}

	// Fall back to default theme
	return defaultTheme.Color(name, variant)
}

func (t *customJSONTheme) Font(style fyne.TextStyle) fyne.Resource {
	if t.data.Fonts == nil {
		return defaultTheme.Font(style)
	}

	var fontKey string
	if style.Monospace {
		fontKey = "monospace"
	} else if style.Bold && style.Italic {
		fontKey = "boldItalic"
	} else if style.Bold {
		fontKey = "bold"
	} else if style.Italic {
		fontKey = "italic"
	} else {
		fontKey = "regular"
	}

	if uriStr, ok := t.data.Fonts[fontKey]; ok {
		if uri, err := storage.ParseURI(uriStr); err == nil {
			return &uriResource{uri: uri}
		}
	}

	return defaultTheme.Font(style)
}

func (t *customJSONTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if t.data.Icons == nil {
		return defaultTheme.Icon(name)
	}

	if uriStr, ok := t.data.Icons[string(name)]; ok {
		if uri, err := storage.ParseURI(uriStr); err == nil {
			return &uriResource{uri: uri}
		}
	}

	return defaultTheme.Icon(name)
}

func (t *customJSONTheme) Size(name fyne.ThemeSizeName) float32 {
	if t.data.Sizes == nil {
		return defaultTheme.Size(name)
	}

	if size, ok := t.data.Sizes[string(name)]; ok {
		return size
	}

	return defaultTheme.Size(name)
}

// parseHexColor parses a hex color string in various formats (3, 4, 6, or 8 digits, with or without # prefix).
func parseHexColor(hex string) (color.Color, error) {
	// Remove # prefix if present
	hex = strings.TrimPrefix(hex, "#")

	// Validate hex characters
	for _, c := range hex {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
			return color.Transparent, fmt.Errorf("invalid hex color format: %s", hex)
		}
	}

	var r, g, b, a uint8
	a = 0xff // Default alpha to fully opaque

	switch len(hex) {
	case 3:
		// RGB format: "abc" -> 0xaa 0xbb 0xcc 0xff
		rv, _ := strconv.ParseUint(string(hex[0]), 16, 8)
		gv, _ := strconv.ParseUint(string(hex[1]), 16, 8)
		bv, _ := strconv.ParseUint(string(hex[2]), 16, 8)
		r, g, b = uint8(rv*17), uint8(gv*17), uint8(bv*17)

	case 4:
		// RGBA format: "abcd" -> 0xaa 0xbb 0xcc 0xdd
		rv, _ := strconv.ParseUint(string(hex[0]), 16, 8)
		gv, _ := strconv.ParseUint(string(hex[1]), 16, 8)
		bv, _ := strconv.ParseUint(string(hex[2]), 16, 8)
		av, _ := strconv.ParseUint(string(hex[3]), 16, 8)
		r, g, b, a = uint8(rv*17), uint8(gv*17), uint8(bv*17), uint8(av*17)

	case 6:
		// RRGGBB format: "a1b2c3" -> 0xa1 0xb2 0xc3 0xff
		val, _ := strconv.ParseUint(hex, 16, 32)
		r = uint8((val >> 16) & 0xff)
		g = uint8((val >> 8) & 0xff)
		b = uint8(val & 0xff)

	case 8:
		// RRGGBBAA format: "a1b2c3f4" -> 0xa1 0xb2 0xc3 0xf4
		val, _ := strconv.ParseUint(hex, 16, 64)
		r = uint8((val >> 24) & 0xff)
		g = uint8((val >> 16) & 0xff)
		b = uint8((val >> 8) & 0xff)
		a = uint8(val & 0xff)

	default:
		return color.Transparent, fmt.Errorf("invalid hex color length: %d", len(hex))
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// uriResource is a simple Resource implementation that holds a URI
type uriResource struct {
	uri fyne.URI
}

func (u *uriResource) Name() string {
	return u.uri.Name()
}

func (u *uriResource) Content() []byte {
	// This would need actual implementation to load the content from the URI
	// For now, return empty to satisfy the interface
	return nil
}

