package binding

import (
	"fmt"
	"sync"
)

// StringFormat supports binding a formatted string value with dynamic inputs.
//
// Since: 2.2
type StringFormat interface {
	String
}

// NewSprintf returns a String binding that format its content using the format string and the provide additional parameter bindings.
// The string will be formatted using fmt.Sprintf and updated when any of the source bindings change.
//
// Since: 2.2
func NewSprintf(format string, b ...DataItem) StringFormat {
	if len(b) == 0 {
		// No bindings, just return a static string with the format
		return NewString().(*boundString)
	}

	ret := &stringFormat{
		format:  format,
		sources: b,
	}
	ret.updateValue()

	// Listen to all source bindings
	for _, source := range b {
		source.AddListener(NewDataListener(func() {
			ret.lock.Lock()
			ret.updateValue()
			ret.lock.Unlock()
			ret.trigger()
		}))
	}

	return ret
}

type stringFormat struct {
	base

	format  string
	sources []DataItem
	current string
	lock    sync.RWMutex
}

func (s *stringFormat) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()
	return s.current, nil
}

func (s *stringFormat) Set(val string) error {
	// StringFormat bindings are read-only since they're computed
	// But we need to implement this to satisfy the String interface
	return fmt.Errorf("cannot set value on a formatted string binding")
}

// updateValue recalculates the formatted string from all sources
// Must be called with lock held
func (s *stringFormat) updateValue() {
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		switch src := source.(type) {
		case Bool:
			if v, err := src.Get(); err == nil {
				values[i] = v
			} else {
				values[i] = false
			}
		case Float:
			if v, err := src.Get(); err == nil {
				values[i] = v
			} else {
				values[i] = 0.0
			}
		case Int:
			if v, err := src.Get(); err == nil {
				values[i] = v
			} else {
				values[i] = 0
			}
		case String:
			if v, err := src.Get(); err == nil {
				values[i] = v
			} else {
				values[i] = ""
			}
		case Untyped:
			if v, err := src.Get(); err == nil {
				values[i] = v
			} else {
				values[i] = nil
			}
		default:
			values[i] = ""
		}
	}
	s.current = fmt.Sprintf(s.format, values...)
}

