package validation

import (
	"errors"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a new validator that ensures the input matches one of the valid options provided.
// The validator will return nil if the input is in the valid list, otherwise returns an error.
//
// Since: 2.2
func NewAllStrings(valid []string) fyne.StringValidator {
	return func(text string) error {
		for _, option := range valid {
			if text == option {
				return nil
			}
		}
		return errors.New("input does not match any valid option")
	}
}

