// NewSprintf returns a String binding that format its content using the format string and the provide additional parameter bindings.
// The string will be formatted using fmt.Sprintf and updated when any of the source bindings change.
//
// Since: 2.2
func NewSprintf(format string, b ...DataItem) StringFormat {
	if len(b) == 0 {
		// No bindings, just return a static string with the format
		return NewString().(*boundString)
	}

	ret := &stringFormat{
		format:  format,
		sources: b,
	}
	ret.updateValue()

	// Listen to all source bindings
	for _, source := range b {
		source.AddListener(NewDataListener(func() {
			ret.lock.Lock()
			ret.updateValue()
			ret.lock.Unlock()
			ret.trigger()
		}))
	}

	return ret
}

// StringToStringWithFormat returns a String binding that formats a source String binding with the given format.
// If the format is "%s" (identity transformation), the original binding is returned directly without wrapping.
// Otherwise, this delegates to NewSprintf(format, str).
//
// Since: 2.2
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		// Identity transformation - return the original binding
		return str
	}
	// Wrap with formatting
	return NewSprintf(format, str)
}

